<?php
namespace App\Services;
class PromoSimulationService
{
 public function simulate(array $input):array{$normal=(float)($input['average_price']??$input['subtotal']??0);$cost=(float)($input['estimated_cost']??0);$transactions=max(0,(int)($input['expected_transactions']??1));$discountType=$input['discount_type']??'percentage';$value=(float)($input['discount_value']??0);$raw=$discountType==='percentage'?$normal*$value/100:$value;$max=isset($input['max_discount'])&&$input['max_discount']!==null?(float)$input['max_discount']:null;$discount=$max===null?$raw:min($raw,$max);$discount=max(0,min($normal,$discount));$afterRevenue=$normal-$discount;$normalMargin=$normal-$cost;$afterMargin=$afterRevenue-$cost;$uplift=max(0,(float)($input['expected_sales_uplift']??0));$normalProjection=$normalMargin*$transactions;$afterProjection=$afterMargin*$transactions*(1+$uplift/100);$multiplier=$afterMargin>0?$normalMargin/$afterMargin:null;$breakEven=$multiplier===null?null:max(0,($multiplier-1)*100);$marginPct=$afterRevenue>0?($afterMargin/$afterRevenue)*100:0;$scores=$this->scores($marginPct,$uplift,$discount/$normal*100,$max!==null,$breakEven,$input['quota']??null);$final=round($scores['margin_safety']*.4+$scores['sales_potential']*.25+$scores['member_attractiveness']*.2+$scores['promo_risk']*.15,2);$status=$final>=80?'AMAN / LAYAK':($final>=60?'PERLU DIPERTIMBANGKAN':'BERISIKO');return['before'=>['revenue'=>$normal,'cost'=>$cost,'margin'=>$normalMargin,'margin_percentage'=>$normal>0?$normalMargin/$normal*100:0],'after'=>['revenue'=>$afterRevenue,'cost'=>$cost,'margin'=>$afterMargin,'margin_percentage'=>$marginPct],'projection'=>['transactions'=>$transactions,'revenue'=>$afterRevenue*$transactions*(1+$uplift/100),'discount'=>$discount*$transactions*(1+$uplift/100),'cost'=>$cost*$transactions*(1+$uplift/100),'margin'=>$afterProjection],'break_even_uplift'=>$breakEven,'scores'=>$scores,'final_score'=>$final,'status'=>$status,'recommendations'=>$this->recommendations($marginPct,$breakEven,$discountType,$max,$final)];}
 public function scores(float $margin,float $uplift,float $discount,bool $hasMax,?float $breakEven,?int $quota):array{$marginScore=$margin>=30?100:($margin>=20?80:($margin>=10?60:($margin>=5?40:($margin>=0?20:0))));$sales=$uplift>=30?100:($uplift>=20?85:($uplift>=10?70:($uplift>=5?55:40)));$attract=$discount<5?40:($discount<10?60:($discount<20?90:($discount<30?100:90)));$risk=100;if($margin<10)$risk-=35;if($discount>=30)$risk-=20;if(!$hasMax)$risk-=15;if($breakEven===null||$breakEven>100)$risk-=20;if($quota===null)$risk-=5;return['margin_safety'=>max(0,$marginScore),'sales_potential'=>$sales,'member_attractiveness'=>$attract,'promo_risk'=>max(0,$risk)];}
 private function recommendations(float $margin,?float $breakEven,string $type,?float $max,float $score):array{$r=[];if($margin<10)$r[]='Kurangi nilai diskon.';if($breakEven!==null&&$breakEven>50)$r[]='Promo membutuhkan kenaikan transaksi yang cukup besar.';if($type==='percentage'&&$max===null)$r[]='Tambahkan batas maksimal potongan.';if($score>=80)$r[]='Promo masih berada pada batas margin yang sehat.';return $r;}
}
